CREATE OR REPLACE FUNCTION private.admin_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.encounter_rounds;
  cfg public.site_config%rowtype;
  seen timestamptz;
  has_token boolean;
  pending int;
  last_err text;
  bits_status text;
  bits_at timestamptz;
  bits_last timestamptz;
  bits_detail text;
  bits_waiting int;
  has_app_secret boolean;
  has_github boolean;
  staff_role text;
  secrets boolean;
begin
  perform private.require_hub();
  staff_role := private.play_staff_role();
  secrets := staff_role = 'owner';
  r := private.pick_play_round();
  select * into cfg from public.site_config where id = 1;
  select b.seen_at, b.token_hash is not null, b.last_error,
         b.eventsub_status, b.eventsub_connected_at, b.last_bits_at, b.last_bits_detail,
         b.twitch_client_secret is not null and btrim(b.twitch_client_secret) <> '',
         b.github_token is not null and btrim(b.github_token) <> ''
    into seen, has_token, last_err, bits_status, bits_at, bits_last, bits_detail, has_app_secret, has_github
    from private.stream_bridge b where b.id = 1;
  select count(*)::int into pending from public.stream_commands where status in ('pending','running');
  select count(*)::int into bits_waiting from private.bits_pending;
  return jsonb_build_object(
    'trainers', (select count(*)::int from public.profiles),
    'passes', (select count(*)::int from public.profiles where starlight_pass),
    'channel', cfg.broadcaster_twitch_login,
    'twitchClientId', case when secrets then cfg.twitch_client_id else null end,
    'twitchBroadcasterId', case when secrets then cfg.twitch_broadcaster_id else null end,
    'twitchClientSecretSaved', case when secrets then coalesce(has_app_secret, false) else null end,
    'githubTokenSaved', case when secrets then coalesce(has_github, false) else null end,
    'live', (select is_live from public.stream_status where id = 1),
    'settings', cfg.game_settings,
    'bitsStoreEnabled', false,
    'staffRole', staff_role,
    'canManageSecrets', secrets,
    'bitsPacks', private.store_catalog()->'bits',
    'round', private.public_round_json(r),
    'bridge', jsonb_build_object(
      'configured', coalesce(has_token, false),
      'online', seen is not null and seen > now() - interval '8 seconds',
      'seenAt', seen,
      'pending', coalesce(pending, 0),
      'lastError', last_err
    ),
    'bitsAuto', jsonb_build_object(
      'connected', coalesce(bits_status, '') = 'enabled',
      'status', bits_status,
      'connectedAt', bits_at,
      'lastAt', bits_last,
      'lastDetail', bits_detail,
      'pending', coalesce(bits_waiting, 0),
      'needsAppSecret', not coalesce(has_app_secret, false)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.require_staff_edit()
 RETURNS void
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  perform private.require_hub();
  if coalesce(private.play_staff_role(), '') not in ('owner', 'admin') then
    raise exception 'Only admins can edit trainer accounts.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_advance_phase()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.encounter_rounds;
  ph text;
  next_ph text;
  clk timestamptz;
  current_end timestamptz;
  delta interval;
  label text;
begin
  perform private.require_hub();
  r := private.pick_play_round();
  if r is null or coalesce(r.cancelled, false) then
    raise exception 'No encounter to skip.';
  end if;
  if not private.deadlines_complete(r.deadlines) then
    raise exception 'This encounter has no phase clock to skip.';
  end if;
  ph := private.round_phase(r);
  if ph is null or ph = 'closed' then
    raise exception 'This encounter is already finished.';
  end if;
  clk := coalesce(r.paused_at, now());
  current_end := (r.deadlines->>ph)::timestamptz;
  if current_end is null then
    raise exception 'This encounter has no phase clock to skip.';
  end if;
  delta := current_end - clk + interval '80 milliseconds';
  if delta < interval '80 milliseconds' then
    delta := interval '80 milliseconds';
  end if;

  update public.encounter_rounds
    set deadlines = jsonb_build_object(
          'join', (deadlines->>'join')::timestamptz - delta,
          'prepare', (deadlines->>'prepare')::timestamptz - delta,
          'throw', (deadlines->>'throw')::timestamptz - delta,
          'reveal', (deadlines->>'reveal')::timestamptz - delta
        ),
        ends_at = ends_at - delta,
        updated_at = now()
    where id = r.id
    returning * into r;

  r := coalesce(private.settle_if_needed(r), r);
  next_ph := private.round_phase(r);
  label := case next_ph
    when 'join' then 'Join'
    when 'prepare' then 'Prepare'
    when 'throw' then 'Throw'
    when 'reveal' then 'the throw animation'
    else 'the end of the encounter'
  end;
  return private.admin_overview() || jsonb_build_object(
    'ok', true,
    'message', 'Skipped to ' || label || '.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_bits_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  connected text;
  last_at timestamptz;
  last_detail text;
  unresolved int := 0;
  failed int := 0;
  pending int := 0;
  duplicates int := 0;
  live_n int := 0;
  invalid int := 0;
  collisions jsonb;
  st text;
begin
  if not private.is_play_admin() then raise exception 'not allowed' using errcode = '42501'; end if;
  select eventsub_status, last_bits_at, last_bits_detail into connected, last_at, last_detail from private.stream_bridge where id = 1;
  select count(*)::int into unresolved from private.bits_events where status in ('unresolved', 'pending');
  select count(*)::int into failed from private.bits_events where status = 'failed';
  select count(*)::int into pending from private.bits_pending;
  select count(*)::int into duplicates from private.bits_events where status = 'duplicate';
  select count(*)::int into live_n from private.bits_live_products();
  select count(*)::int into invalid
    from private.store_items i
    join private.store_categories c on c.id = i.category_id
   where c.kind = 'bits' and private.store_item_is_live(i)
     and (i.bits < 1 or i.grants = '{}'::jsonb or coalesce(jsonb_array_length(i.extra->'bitsTitles'), 0) < 1
          or i.grants ? 'masterball' or i.grants ? 'odds' or i.grants ? 'random');
  collisions := private.bits_amount_collisions();
  st := case
    when failed > 0 or invalid > 0 then 'ACTION NEEDED'
    when unresolved + pending > 0 or jsonb_array_length(collisions) > 0 or coalesce(connected, '') is distinct from 'enabled' then 'WARNING'
    when last_at is null then 'UNKNOWN'
    else 'HEALTHY'
  end;
  return jsonb_build_object(
    'ok', true, 'status', st,
    'eventSub', coalesce(connected, ''),
    'lastVerifiedAt', last_at,
    'lastDetail', last_detail,
    'unresolved', unresolved, 'failed', failed, 'pending', pending, 'duplicates', duplicates,
    'liveProducts', live_n, 'invalidProducts', invalid, 'collisions', collisions,
    'detail', case
      when failed > 0 then 'A verified Bits event failed after Twitch accepted it. Use Retry fulfillment.'
      when invalid > 0 then 'A live Bits product is missing titles, contents, or a positive Bits cost.'
      when jsonb_array_length(collisions) > 0 then 'Two live Power-Ups share a Bits amount.'
      when unresolved + pending > 0 then 'Some Power-Ups are waiting for a linked Trainer.'
      when coalesce(connected, '') is distinct from 'enabled' then 'EventSub is not enabled.'
      when last_at is null then 'No verified Bits events have arrived yet. That is UNKNOWN, not broken.'
      else 'Bits fulfillment is connected.'
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_bits_qa_redemption(p_login text, p_title text, p_bits integer, p_twitch_user_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  eid text := 'qa:' || replace(gen_random_uuid()::text, '-', '');
  login text := lower(btrim(coalesce(p_login, '')));
  ident text := btrim(coalesce(p_twitch_user_id, ''));
begin
  perform private.require_staff_edit();
  if login not like 'qa-%' and ident not like 'qa-%' then
    raise exception 'QA Bits events must use a qa- identity so they cannot grant a live Trainer.';
  end if;
  return public.credit_bits_from_twitch(eid, p_login, p_title, p_bits, p_twitch_user_id)
    || jsonb_build_object('qa', true, 'eventId', eid);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_bits_retry(p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ev private.bits_events%rowtype;
begin
  perform private.require_staff_edit();
  select * into ev from private.bits_events where event_id = btrim(coalesce(p_event_id, ''));
  if not found then raise exception 'That Bits event was not found.'; end if;
  if ev.granted or ev.status = 'fulfilled' then
    return jsonb_build_object('ok', true, 'duplicate', true, 'message', 'Already fulfilled. Retry will not grant again.');
  end if;
  if ev.status in ('ignored', 'skipped_bot') then
    raise exception 'This event is not eligible for retry (%).', ev.status;
  end if;
  delete from private.bits_events where event_id = ev.event_id;
  return public.credit_bits_from_twitch(ev.event_id, ev.twitch_login, ev.title, ev.bits, ev.twitch_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_build_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  mig text;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  begin
    select version into mig
    from supabase_migrations.schema_migrations
    order by version desc
    limit 1;
  exception when others then
    mig := null;
  end;
  return jsonb_build_object(
    'ok', true,
    'clientBuild', private.client_build(),
    'dbMigration', mig
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cancel_round()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.encounter_rounds;
  rec public.encounter_players%rowtype;
begin
  perform private.require_hub();
  r := private.load_play_round(null);
  if r is null or r.cancelled then
    raise exception 'No encounter to cancel.';
  end if;
  if not r.resolved then
    for rec in select * from public.encounter_players where round_id = r.id
    loop
      perform private.restore_bag_item(rec.user_id, rec.prep);
      if rec.throw_processed and rec.result_reason is distinct from 'no_ball_left' then
        perform private.restore_bag_item(rec.user_id, rec.ball);
      end if;
    end loop;
  end if;
  update public.encounter_rounds
    set cancelled = true,
        resolved = true,
        hidden = true,
        phase = 'closed',
        paused_at = null,
        last_action = 'Encounter cancelled',
        updated_at = now()
    where id = r.id;
  perform private.staff_console(r.id, 'cancel', null, 'Encounter cancelled.');
  return private.admin_overview() || jsonb_build_object('ok', true, 'message', 'Encounter cancelled.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_candy_simulate(p_family integer, p_catches integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  fam public.evolution_families;
  spec public.species;
  pay int;
  first_rule public.evolution_rules;
  final_rule public.evolution_rules;
  mid_pay int := 5;
begin
  if not private.is_play_admin() then raise exception 'Admin only.'; end if;
  select * into fam from public.evolution_families where id = p_family;
  if fam.id is null then raise exception 'Unknown family.'; end if;
  select * into spec from public.species where dex = fam.base_dex;
  pay := private.candy_for_stage(coalesce(spec.evo_stage, 1));
  select * into first_rule from public.evolution_rules
   where family_id = p_family and enabled and to_dex between 1 and 151
   order by sort_order limit 1;
  select * into final_rule from public.evolution_rules
   where family_id = p_family and enabled and to_dex between 1 and 151
   order by sort_order desc limit 1;
  return jsonb_build_object(
    'ok', true,
    'family', fam.name,
    'balanceVersion', coalesce((select balance_version from public.evolution_config where id = 1), 1),
    'candyPerCatch', pay,
    'expectedCatches', p_catches,
    'expectedCandy', greatest(p_catches, 0) * pay,
    'note', 'Range assumes first-stage catches. Natural evolved spawns and trades can shorten this.',
    'firstEvolution', case when first_rule.id is null then null else jsonb_build_object(
      'fromDex', first_rule.from_dex, 'toDex', first_rule.to_dex, 'cost', first_rule.candy_cost,
      'catchesNeeded', ceil(first_rule.candy_cost::numeric / greatest(pay, 1)),
      'range', 'About ' || ceil(first_rule.candy_cost::numeric / greatest(pay, 1))::text || ' first-stage catches if only this stage contributes.'
    ) end,
    'finalEvolution', case when final_rule.id is null or final_rule.id = first_rule.id then null else jsonb_build_object(
      'fromDex', final_rule.from_dex, 'toDex', final_rule.to_dex, 'cost', final_rule.candy_cost,
      'catchesNeeded', ceil((coalesce(first_rule.candy_cost, 0) + final_rule.candy_cost)::numeric / greatest(pay, 1)),
      'additionalIfOnlyFirst', ceil(final_rule.candy_cost::numeric / greatest(pay, 1)),
      'fasterIfMiddleCaught', ceil(final_rule.candy_cost::numeric / mid_pay),
      'range', 'After the first evolution, about ' || ceil(final_rule.candy_cost::numeric / greatest(pay, 1))::text || ' more first-stage catches, or fewer if middle stages are caught.'
    ) end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_capture_inspect(p_round uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  rid uuid := p_round;
  r public.encounter_rounds;
  rows jsonb;
  honey jsonb;
  players jsonb;
begin
  perform private.require_hub();
  if rid is null then
    select id into rid from public.encounter_rounds order by started_at desc limit 1;
  end if;
  select * into r from public.encounter_rounds where id = rid;
  if r is null then
    raise exception 'No round to inspect.';
  end if;
  select coalesce(jsonb_agg(to_jsonb(cl) order by cl.created_at), '[]'::jsonb)
    into rows
    from public.capture_log cl
   where cl.round_id = rid;
  select coalesce(jsonb_agg(jsonb_build_object(
      'userId', ep.user_id,
      'name', coalesce(private.trainer_label(ep.user_id), 'Trainer'),
      'prep', ep.prep,
      'ball', ep.ball,
      'result', ep.result,
      'caught', ep.caught,
      'chance', ep.chance,
      'roll', ep.roll
    ) order by coalesce(private.trainer_label(ep.user_id), 'Trainer')), '[]'::jsonb)
    into players
    from public.encounter_players ep
   where ep.round_id = rid;
  select jsonb_build_object(
      'contributors', count(*) filter (where prep = 'bait'),
      'participants', count(*),
      'names', coalesce(jsonb_agg(coalesce(private.trainer_label(user_id), 'Trainer')) filter (where prep = 'bait'), '[]'::jsonb)
    )
    into honey
    from public.encounter_players
   where round_id = rid;
  return jsonb_build_object(
    'ok', true,
    'roundId', r.id,
    'dex', r.dex,
    'name', r.name,
    'variant', r.variant,
    'gender', r.gender,
    'level', r.pokemon->>'level',
    'location', r.pokemon->>'location',
    'triggerSource', r.trigger_source,
    'testOutcome', r.rules->>'testOutcome',
    'honey', honey,
    'players', players,
    'captureLog', rows
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_capture_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'ok', true,
    'balance', private.capture_config(),
    'balls', coalesce((
      select jsonb_agg(to_jsonb(b) order by b.sort_order, b.name) from public.capture_balls b
    ), '[]'::jsonb),
    'berries', coalesce((
      select jsonb_agg(to_jsonb(b) order by b.sort_order, b.name) from public.capture_berries b
    ), '[]'::jsonb),
    'species', coalesce((
      select jsonb_agg(jsonb_build_object(
        'dex', s.dex, 'name', s.name, 'catchRate', s.catch_rate,
        'baseChance', private.capture_base_chance(s.catch_rate),
        'types', s.types, 'baseSpeed', s.base_speed, 'weightKg', s.weight_kg,
        'moonStoneFamily', s.moon_stone_family
      ) order by s.dex)
      from public.species s
    ), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_capture_save_balance(p_balance jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  next_balance jsonb;
  min_c numeric;
  max_c numeric;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  next_balance := private.capture_config() || coalesce(p_balance, '{}'::jsonb);
  min_c := coalesce((next_balance->>'minChance')::numeric, 0.02);
  max_c := coalesce((next_balance->>'maxChance')::numeric, 0.85);
  if min_c < 0 or min_c > 1 or max_c < 0 or max_c > 1 then
    raise exception 'Chance limits must be between 0 and 1.';
  end if;
  if min_c >= max_c then
    raise exception 'The minimum chance must be lower than the maximum chance.';
  end if;
  if coalesce((next_balance->>'maxChance')::numeric, 0) >= 1 then
    raise exception 'Only the Master Ball may guarantee a capture.';
  end if;
  update public.site_config
     set game_settings = coalesce(game_settings, '{}'::jsonb)
       || jsonb_build_object('captureBalance', next_balance),
         updated_at = now()
   where id = 1;
  return jsonb_build_object('ok', true, 'balance', next_balance, 'message', 'Capture balance saved.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_capture_simulate(p_dex integer, p_ball text DEFAULT 'pokeball'::text, p_berry text DEFAULT NULL::text, p_joined integer DEFAULT 1, p_honey integer DEFAULT 0, p_contributed boolean DEFAULT false, p_owns boolean DEFAULT false, p_shiny boolean DEFAULT false, p_trials integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  calc jsonb;
  trials int := least(greatest(coalesce(p_trials, 0), 0), 100000);
  wins int := 0;
  i int;
  chance numeric;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  calc := private.capture_chance(
    p_dex, p_ball, p_berry, p_honey, p_joined, p_contributed, p_owns, p_shiny, 1.0, now()
  );
  chance := (calc->>'finalChance')::numeric;
  if trials > 0 then
    for i in 1..trials loop
      if private.secure_random() < chance then
        wins := wins + 1;
      end if;
    end loop;
  end if;
  return jsonb_build_object(
    'ok', true,
    'calc', calc,
    'trials', trials,
    'successes', wins,
    'observedRate', case when trials > 0 then round(wins::numeric / trials, 4) else null end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_clear_console()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform private.require_hub();
  delete from public.play_console_log where id is not null;
  delete from public.encounter_activity where id is not null;
  return private.admin_overview() || jsonb_build_object(
    'ok', true,
    'message', 'Public encounter log cleared.',
    'console', private.play_console_json(250)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_clear_round()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.encounter_rounds;
  ph text;
begin
  perform private.require_hub();
  r := private.pick_play_round();
  if r is null then
    raise exception 'No encounter to clear.';
  end if;
  ph := private.round_phase(r);
  if r.paused_at is null
     and coalesce(r.resolved, false) = false
     and ph in ('join', 'prepare', 'throw') then
    raise exception 'Cancel a live encounter instead of clearing it.';
  end if;
  update public.encounter_rounds
    set hidden = true,
        phase = 'closed',
        last_action = coalesce(nullif(btrim(last_action), ''), 'Encounter cleared'),
        updated_at = now()
    where id = r.id;
  return private.admin_overview() || jsonb_build_object('ok', true, 'message', 'Encounter cleared from Play and the hub.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_content_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  missing_icon int := 0; broken_pack int := 0; missing_portrait int := 0; dual_currency int := 0; neg int := 0;
  bits_invalid int := 0; collisions jsonb;
begin
  if not private.is_play_admin() then raise exception 'not allowed' using errcode = '42501'; end if;
  select count(*)::int into missing_icon from private.store_items i where private.store_item_is_live(i) and coalesce(i.sprite,'') = '' and coalesce(i.thumb,'') = '';
  select count(*)::int into broken_pack from private.store_items i where coalesce(i.extra->>'productKind','') = 'pack' and (i.grants is null or i.grants = '{}'::jsonb);
  select count(*)::int into missing_portrait from private.trainer_looks where visible and coalesce(portrait_file,'') = '';
  select count(*)::int into dual_currency from private.store_items where cost > 0 and bits > 0;
  select count(*)::int into neg from public.inventories where coalesce(coins,0) < 0 or coalesce(pokeball,0) < 0;
  select count(*)::int into bits_invalid
    from private.store_items i join private.store_categories c on c.id = i.category_id
   where c.kind = 'bits' and private.store_item_is_live(i)
     and (i.bits < 1 or i.grants = '{}'::jsonb or coalesce(jsonb_array_length(i.extra->'bitsTitles'), 0) < 1);
  collisions := private.bits_amount_collisions();
  return jsonb_build_object(
    'ok', missing_icon + broken_pack + dual_currency + neg + bits_invalid + jsonb_array_length(collisions) = 0,
    'status', case when missing_icon + broken_pack + dual_currency + neg + bits_invalid > 0 then 'WARNING'
                   when jsonb_array_length(collisions) > 0 then 'WARNING'
                   else 'HEALTHY' end,
    'missingIcons', missing_icon, 'brokenPacks', broken_pack, 'missingPortraits', missing_portrait,
    'dualCurrency', dual_currency, 'negativeInventory', neg,
    'bitsInvalid', bits_invalid, 'bitsCollisions', collisions,
    'detail', format('%s live products, %s missing portraits, %s broken packs, %s invalid Bits products',
      (select count(*) from private.store_items i where private.store_item_is_live(i)), missing_portrait, broken_pack, bits_invalid)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_content_picker(p_q text DEFAULT NULL::text, p_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  q text := lower(btrim(coalesce(p_q, '')));
  kind text := lower(btrim(coalesce(p_kind, 'all')));
begin
  perform private.require_staff_edit();
  return jsonb_build_object(
    'ok', true,
    'items', case when kind in ('all','items','balls','berries') then coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', 'item', 'key', x.row->>'key', 'name', x.row->>'name',
        'category', x.row->>'category', 'identity', x.row
      ) order by x.row->>'category', x.row->>'name')
      from (
        select private.item_identity(b.key) as row from public.capture_balls b
        union all
        select private.item_identity(r.key) from public.capture_berries r where r.capture_enabled or r.store_available
        union all
        select private.item_identity(k) from unnest(array['bait','lure','bag_bonus','rarecandy','firestone','waterstone','thunderstone','leafstone','moonstone','linkingcord']) k
      ) x
      where q = '' or x.row->>'name' ilike '%'||q||'%' or x.row->>'key' ilike '%'||q||'%'
    ), '[]'::jsonb) else '[]'::jsonb end,
    'avatars', case when kind in ('all','avatars') then coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', 'avatar', 'key', l.id, 'name', l.name, 'pack', l.pack_key,
        'portrait', l.portrait_file, 'ext', l.ext
      ) order by l.sort, l.name)
      from private.trainer_looks l
      where l.visible and (q = '' or l.name ilike '%'||q||'%' or l.id ilike '%'||q||'%')
    ), '[]'::jsonb) else '[]'::jsonb end,
    'avatarPacks', case when kind in ('all','avatars','packs') then coalesce((
      select jsonb_agg(jsonb_build_object('kind','avatarPack','key', i.extra->>'pack', 'name', i.name, 'sku', i.sku) order by i.name)
      from private.store_items i
      where nullif(i.extra->>'pack','') is not null
        and (q = '' or i.name ilike '%'||q||'%')
    ), '[]'::jsonb) else '[]'::jsonb end,
    'cosmetics', case when kind in ('all','cosmetics') then coalesce((
      select jsonb_agg(jsonb_build_object('kind','cosmetic','key', c.id, 'name', c.name, 'slot', c.kind) order by c.sort_order, c.name)
      from public.progression_cosmetics c
      where c.enabled and (q = '' or c.name ilike '%'||q||'%' or c.id ilike '%'||q||'%')
    ), '[]'::jsonb) else '[]'::jsonb end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_event(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
