$function$

CREATE OR REPLACE FUNCTION public.admin_economy_save(p_balance jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare next_bal jsonb;
begin
  if not private.is_play_admin() then raise exception 'not allowed' using errcode='42501'; end if;
  next_bal := private.economy_config() || coalesce(p_balance,'{}'::jsonb);
  if coalesce((next_bal->>'participationReward')::int,0) < 0 or coalesce((next_bal->>'captureReward')::int,0) < 0 then raise exception 'Rewards cannot be negative.'; end if;
  update public.site_config set game_settings = coalesce(game_settings,'{}'::jsonb) || jsonb_build_object('economyBalance', next_bal), updated_at = now() where id = 1;
  return jsonb_build_object('ok', true, 'config', next_bal, 'message', 'Economy balance saved.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_economy_simulate(p_encounters integer DEFAULT 10, p_streams integer DEFAULT 5, p_join_rate numeric DEFAULT 0.8, p_catch_rate numeric DEFAULT 0.35, p_new_dex_rate numeric DEFAULT 0.25, p_strategy text DEFAULT 'regular'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb := private.economy_config(); encounters int := least(greatest(coalesce(p_encounters,10),1),2500); streams int := least(greatest(coalesce(p_streams,5),1),20); joined numeric; caught numeric; earned int; weekly int; poke int; great int; ultra int;
begin
  if not private.is_play_admin() then raise exception 'not allowed' using errcode='42501'; end if;
  joined := encounters * least(greatest(coalesce(p_join_rate,0.8),0),1);
  caught := joined * least(greatest(coalesce(p_catch_rate,0.35),0),1);
  earned := (coalesce((cfg->>'streamAttendanceReward')::int,50) + floor(joined*coalesce((cfg->>'participationReward')::int,25)) + floor(caught*coalesce((cfg->>'captureReward')::int,25)) + floor(caught*least(greatest(coalesce(p_new_dex_rate,0.25),0),1)*coalesce((cfg->>'newDexReward')::int,100)) + coalesce((cfg->'dailySupply'->>'coins')::int,50))::int;
  weekly := earned * streams;
  poke := coalesce((select shop_price from public.capture_balls where key='pokeball'),100);
  great := coalesce((select shop_price from public.capture_balls where key='greatball'),225);
  ultra := coalesce((select shop_price from public.capture_balls where key='ultraball'),500);
  return jsonb_build_object('ok',true,'dryRun',true,'strategy',coalesce(p_strategy,'regular'),
    'perStream', jsonb_build_object('encounters',encounters,'joined',round(joined,2),'caught',round(caught,2),'coinsEarned',earned,'pokeBallsAffordable',earned/poke,'greatBallsAffordable',earned/great,'ultraBallsAffordable',earned/ultra),
    'weekly', jsonb_build_object('streams',streams,'coinsEarned',weekly,'pokeBallsAffordable',weekly/poke,'greatBallsAffordable',weekly/great,'ultraBallsAffordable',weekly/ultra,'note','Dry run only. No inventories were changed.'));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_game_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  mig text;
  rounds_24 int := 0;
  resolved_24 int := 0;
  cancelled_24 int := 0;
  cancelled_open int := 0;
  cancelled_unresolved_closed int := 0;
  neg_coins int := 0;
  neg_balls int := 0;
  neg_candy int := 0;
  twitch_live boolean;
  twitch_login text;
  client_build text;
  app_status text;
  db_status text;
  enc_status text;
  eco_status text;
  auth_status text;
  twitch_status text;
  rank_eligible int := 0;
  rank_hidden int := 0;
  rank_bot_only int := 0;
  rank_dup_login int := 0;
  rank_null_xp int := 0;
  rank_status text;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  begin
    select version into mig from supabase_migrations.schema_migrations order by version desc limit 1;
  exception when others then
    mig := null;
  end;
  client_build := private.client_build();
  select count(*)::int,
         count(*) filter (where resolved)::int,
         count(*) filter (where cancelled)::int
    into rounds_24, resolved_24, cancelled_24
    from public.encounter_rounds
   where started_at > now() - interval '24 hours'
      or updated_at > now() - interval '24 hours';
  select count(*)::int into cancelled_open
    from public.encounter_rounds
   where cancelled and coalesce(phase, '') is distinct from 'closed';
  select count(*)::int into cancelled_unresolved_closed
    from public.encounter_rounds
   where cancelled and not resolved and coalesce(phase, '') = 'closed';
  select count(*)::int into neg_coins from public.inventories where coalesce(coins, 0) < 0;
  select count(*)::int into neg_balls
    from public.inventories
   where coalesce(pokeball, 0) < 0 or coalesce(greatball, 0) < 0 or coalesce(ultraball, 0) < 0
      or coalesce((balls->>'masterball')::int, 0) < 0;
  select count(*)::int into neg_candy from public.family_candy where coalesce(qty, 0) < 0;
  select is_live into twitch_live from public.stream_status where id = 1;
  select broadcaster_twitch_login into twitch_login from public.site_config where id = 1;

  select count(*) filter (where private.ranking_eligible_uid(p.id))::int,
         count(*) filter (where not p.ranking_visible)::int,
         count(*) filter (
           where p.ranking_visible
             and nullif(p.username, '') is null
             and exists (
               select 1 from public.twitch_connections c
                where c.user_id = p.id and c.confirmed and c.connection_type = 'bot'
             )
             and not exists (
               select 1 from public.twitch_connections c
                where c.user_id = p.id and c.confirmed and c.connection_type in ('player', 'secondary')
             )
         )::int,
         count(*) filter (where p.xp is null)::int
    into rank_eligible, rank_hidden, rank_bot_only, rank_null_xp
    from public.profiles p;
  select count(*)::int into rank_dup_login
    from (
      select coalesce(nullif(twitch_login, ''), nullif(username, '')) as k
      from public.profiles
      where coalesce(nullif(twitch_login, ''), nullif(username, '')) is not null
      group by 1
      having count(*) > 1
    ) d;

  app_status := case
    when coalesce(client_build, '') = '' then 'WARNING'
    else 'HEALTHY'
  end;
  db_status := case when mig is null then 'UNKNOWN' else 'HEALTHY' end;
  enc_status := case
    when cancelled_open > 0 then 'ACTION NEEDED'
    else 'HEALTHY'
  end;
  eco_status := case
    when neg_coins > 0 or neg_balls > 0 or neg_candy > 0 then 'ACTION NEEDED'
    else 'HEALTHY'
  end;
  auth_status := 'UNKNOWN';
  twitch_status := case
    when coalesce(twitch_login, '') = '' then 'WARNING'
    when twitch_live then 'HEALTHY'
    else 'HEALTHY'
  end;
  rank_status := case
    when rank_dup_login > 0 or rank_null_xp > 0 then 'WARNING'
    else 'HEALTHY'
  end;

  return jsonb_build_object(
    'ok', true,
    'application', jsonb_build_object(
      'status', app_status,
      'clientBuild', client_build,
      'dbMigration', mig,
      'detail', 'Reuse Build Health for APP_BUILD / sprite / stale-client.'
    ),
    'database', jsonb_build_object(
      'status', db_status,
      'dbMigration', mig,
      'detail', case when mig is null then 'Migration catalog unavailable.' else 'Latest applied migration listed.' end
    ),
    'encounters', jsonb_build_object(
      'status', enc_status,
      'recent24h', rounds_24,
      'resolved24h', resolved_24,
      'cancelled24h', cancelled_24,
      'cancelledOpen', cancelled_open,
      'cancelledUnresolvedClosed', cancelled_unresolved_closed,
      'detail', case
        when cancelled_open > 0 then 'A cancelled round is not closed.'
        when cancelled_unresolved_closed > 0 then 'Historical cancelled rounds may still have resolved=false. Future cancels set resolved=true. Not live blockers.'
        else 'No open cancelled rounds.'
      end
    ),
    'economy', jsonb_build_object(
      'status', eco_status,
      'negativeCoins', neg_coins,
      'negativeBalls', neg_balls,
      'negativeCandy', neg_candy,
      'detail', case
        when neg_coins + neg_balls + neg_candy > 0 then 'Negative quantities found. Do not auto-repair.'
        else 'No negative currency, balls, or Evolution Candy.'
      end
    ),
    'auth', jsonb_build_object(
      'status', auth_status,
      'detail', 'Leaked-password protection is a Supabase Auth dashboard setting, not a database flag.'
    ),
    'twitch', jsonb_build_object(
      'status', twitch_status,
      'streamAccount', twitch_login,
      'live', coalesce(twitch_live, false),
      'detail', 'Live controls stay on Dashboard / Stream Session.'
    ),
    'assets', jsonb_build_object(
      'status', 'UNKNOWN',
      'detail', 'Asset HEAD checks and fallbacks are client-side. Use Encounter Asset Health.'
    ),
    'performance', jsonb_build_object(
      'status', 'UNKNOWN',
      'detail', 'Performance mode is a Trainer preference (AUTO/HIGH/BALANCED/LOW).'
    ),
    'rankings', jsonb_build_object(
      'status', rank_status,
      'eligible', rank_eligible,
      'excludedHidden', rank_hidden,
      'excludedBotOnly', rank_bot_only,
      'duplicatePublicKeys', rank_dup_login,
      'nullXp', rank_null_xp,
      'period', 'lifetime',
      'honeyMetric', 'trainer_stats.honey — Honey contributed on finished non-test encounters (prep = bait). Not inventories.bait / Store purchases.',
      'detail', format(
        'Eligible %s · hidden %s · bot-only %s · duplicate keys %s. Honey ranks contribution, not spending.',
        rank_eligible, rank_hidden, rank_bot_only, rank_dup_login
      )
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_gift_joined(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.encounter_rounds;
  v_key text;
  grants jsonb;
  uid uuid;
  given int := 0;
  skipped int := 0;
  joiners int := 0;
  label text;
begin
  perform private.require_hub();
  v_key := btrim(lower(coalesce(p_key, '')));
  if v_key = '' then
    raise exception 'Pick a supply or Poké Ball.';
  end if;
  if v_key not in ('berry', 'bait', 'lure', 'pokeball', 'greatball', 'ultraball', 'bag_bonus')
     and not (v_key = any (private.extra_ball_keys())) then
    raise exception 'That item cannot be gifted.';
  end if;
  r := private.sync_latest_round();
  if not private.round_is_active(r) then
    raise exception 'Start an encounter first.';
  end if;
  select count(*)::int into joiners from public.encounter_players where round_id = r.id;
  if joiners < 1 then
    raise exception 'No trainers have joined this encounter yet.';
  end if;
  grants := jsonb_build_object(v_key, 1);
  label := case v_key
    when 'bag_bonus' then 'Bag space'
    when 'lure' then 'Poké Radar'
    else private.item_label(v_key)
  end;
  for uid in select user_id from public.encounter_players where round_id = r.id loop
    begin
      perform private.grant_known(uid, grants);
      given := given + 1;
    exception when others then
      skipped := skipped + 1;
    end;
  end loop;
  update public.encounter_rounds
    set last_action = format('Staff sent +1 %s', label),
        updated_at = now()
    where id = r.id;
  perform private.staff_console(
    r.id,
    'gift',
    v_key,
    format('Sent +1 %s to %s trainer%s%s.',
      label,
      given,
      case when given = 1 then '' else 's' end,
      case when skipped > 0 then format(' (%s bag%s full)', skipped, case when skipped = 1 then '' else 's' end) else '' end
    )
  );
  return private.admin_overview() || jsonb_build_object(
    'ok', true,
    'given', given,
    'skipped', skipped,
    'message', format('Gave +1 %s to %s trainer%s who joined.', label, given, case when given = 1 then '' else 's' end)
  );
end;
$function$

