CREATE OR REPLACE FUNCTION public.admin_progression_save(p_balance jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  next_bal jsonb;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  next_bal := private.progression_config() || coalesce(p_balance, '{}'::jsonb);
  if coalesce((next_bal->>'xpBase')::int, 0) < 1 or coalesce((next_bal->>'maxLevel')::int, 0) < 1 then
    raise exception 'XP curve values are not valid.';
  end if;
  if coalesce((next_bal->>'levelCatchBonus')::boolean, false) then
    raise exception 'Trainer Level must not change catch chance.';
  end if;
  update public.site_config
     set game_settings = coalesce(game_settings, '{}'::jsonb)
       || jsonb_build_object('progressionBalance', next_bal),
         updated_at = now()
   where id = 1;
  return jsonb_build_object('ok', true, 'config', next_bal, 'message', 'Progression balance saved.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_qa_grant_pass_reward(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  admin uuid := auth.uid();
  kind text := lower(btrim(coalesce(p_kind, '')));
  v_grants jsonb;
  label text;
  supply jsonb;
  berry jsonb;
begin
  if admin is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if kind not in ('daily', 'weekly', 'supply') then
    raise exception 'Unknown Pass QA reward kind.';
  end if;
  if kind = 'supply' then
    supply := private.economy_config()->'dailySupply';
    berry := private.pick_loot_entry('DAILY_COMMON_BERRY');
    if berry is null or (berry->>'item') = 'goldenrazz' then
      berry := jsonb_build_object('item', 'berry', 'qty', 1);
    end if;
    v_grants := jsonb_build_object(
        'pokeball', coalesce((supply->>'pokeball')::int, 3),
        berry->>'item', coalesce((supply->>'berry')::int, 1),
        'coins', coalesce((supply->>'coins')::int, 50)
      ) || coalesce(private.daily_streak_bonus(1), '{}'::jsonb);
    label := 'ADMIN QA Daily Trainer Supply';
  else
    v_grants := private.pass_reward_grants(kind);
    label := case when kind = 'daily' then 'ADMIN QA Daily Pass' else 'ADMIN QA Weekly Pass' end;
  end if;
  if v_grants is null or v_grants = '{}'::jsonb then
    raise exception 'QA reward bundle is empty.';
  end if;
  perform private.grant_items(
    admin,
    v_grants,
    'ADMIN_QA',
    'pass-qa-' || kind,
    'admin-pass-qa:' || admin::text || ':' || kind || ':' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS'),
    true
  );
  insert into public.admin_qa_grants (admin_id, target_user, kind, payload)
  values (
    admin,
    admin,
    'PASS_REWARD_QA',
    jsonb_build_object('passKind', kind, 'grants', v_grants, 'label', label)
  );
  return private.play_snapshot(admin) || jsonb_build_object(
    'ok', true,
    'qa', true,
    'kind', kind,
    'grants', v_grants,
    'message', label || ' granted: ' || private.grant_summary(v_grants) || '.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_queue_stream_command(p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cmd uuid;
  pending int;
  seen timestamptz;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_action not in ('start','cancel','hide','resume','refill','settings') then
    raise exception 'Unknown Mix It Up command.';
  end if;
  cmd := private.enqueue_stream_command(p_action, coalesce(p_payload, '{}'::jsonb));
  select count(*)::int into pending from public.stream_commands where status = 'pending';
  select seen_at into seen from private.stream_bridge where id = 1;
  return jsonb_build_object(
    'ok', true,
    'id', cmd,
    'pending', pending,
    'bridgeOnline', seen is not null and seen > now() - interval '8 seconds',
    'message', case
      when seen is not null and seen > now() - interval '8 seconds'
        then 'Sent to Mix It Up on the stream PC.'
      else 'Queued. Open Mix It Up so Application Launch can start the bridge.'
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_refill_test()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  settings jsonb;
  changed int;
begin
  perform private.require_hub();
  settings := private.game_settings();
  update public.inventories i
    set berry = greatest(i.berry, coalesce((settings->'starterItems'->>'berry')::int, 10)),
        bait = greatest(i.bait, coalesce((settings->'starterItems'->>'bait')::int, 10)),
        pokeball = greatest(i.pokeball, coalesce((settings->'starterItems'->>'pokeball')::int, 10)),
        greatball = greatest(i.greatball, coalesce((settings->'starterItems'->>'greatball')::int, 5)),
        ultraball = greatest(i.ultraball, coalesce((settings->'starterItems'->>'ultraball')::int, 3)),
        updated_at = now();
  get diagnostics changed = row_count;
  return private.play_snapshot(auth.uid()) || jsonb_build_object(
    'ok', true,
    'message', format('Free test refill: topped up %s trainer bag(s). Collections were left alone.', changed)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_pokemon(p_user uuid, p_catch_id uuid)
