    update public.profiles set card_frame = 'plain', updated_at = now()
     where id = p_user and card_frame = private.cosmetic_asset(p_id);
  end if;
  insert into public.play_console_log (kind, message)
  values ('admin', 'Staff revoked cosmetic ' || p_id || coalesce(' (' || p_reason || ')', ''));
  return public.admin_identity_inspect(p_user) || jsonb_build_object('message', 'Cosmetic revoked.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_event(p_id uuid, p_title text, p_blurb text, p_kind text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  event_id uuid;
  title text := btrim(coalesce(p_title, ''));
  kind text := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), 'community');
begin
  if not private.is_play_admin() then
    raise exception 'Staff only.' using errcode = '42501';
  end if;
  if char_length(title) < 2 then
    raise exception 'Give the event a title.';
  end if;
  if p_starts_at is null then
    raise exception 'Pick a start time.';
  end if;
  if kind not in ('community', 'shiny', 'raid', 'stream', 'other') then
    kind := 'community';
  end if;
  if p_id is null then
    insert into public.play_events (title, blurb, kind, starts_at, ends_at)
    values (title, coalesce(p_blurb, ''), kind, p_starts_at, p_ends_at)
    returning id into event_id;
  else
    update public.play_events
      set title = title, blurb = coalesce(p_blurb, ''), kind = kind, starts_at = p_starts_at, ends_at = p_ends_at, updated_at = now()
      where id = p_id returning id into event_id;
    if event_id is null then raise exception 'That event was not found.'; end if;
  end if;
  return jsonb_build_object('ok', true, 'id', event_id, 'message', 'Event saved.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_game_settings(p_settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  next_settings jsonb;
  keys text[] := array['joinSeconds','prepareSeconds','throwSeconds','revealSeconds'];
  k text;
  v numeric;
begin
  if not private.is_play_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  next_settings := coalesce(private.game_settings(), '{}'::jsonb);
  foreach k in array keys
  loop
    v := (p_settings->>k)::numeric;
    if v is null or v < 5 or v > 180 then
      raise exception '% must be between 5 and 180 seconds.', k;
    end if;
    next_settings := jsonb_set(next_settings, array[k], to_jsonb(v));
  end loop;
  update public.site_config
    set game_settings = next_settings, bits_store_enabled = false, updated_at = now()
    where id = 1;
  return private.play_snapshot(auth.uid()) || jsonb_build_object('ok', true, 'message', 'Encounter timings saved. Bits purchases stay off.');
end;
$function$

