CREATE OR REPLACE FUNCTION public.admin_store_duplicate_item(p_sku text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare src private.store_items; v_sku text;
begin
  perform private.require_staff_edit();
  select * into src from private.store_items where sku = p_sku;
  if src.sku is null then raise exception 'Unknown product.'; end if;
  v_sku := src.sku || '-copy';
  if exists (select 1 from private.store_items where sku = v_sku) then v_sku := src.sku || '-copy-' || substr(gen_random_uuid()::text, 1, 8); end if;
  insert into private.store_items (sku, category_id, name, blurb, cost, bits, grants, sprite, thumb, featured, sort, visible, extra, status)
  values (v_sku, src.category_id, src.name || ' Copy', src.blurb, src.cost, src.bits, src.grants, src.sprite, src.thumb, false, src.sort + 1, false, coalesce(src.extra,'{}'::jsonb) || jsonb_build_object('status','draft'), 'draft');
  return public.admin_store_get() || jsonb_build_object('ok', true, 'sku', v_sku, 'message', 'Duplicated as a draft.');
end;$function$

CREATE OR REPLACE FUNCTION public.admin_store_get()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform private.require_hub();
  return jsonb_build_object(
    'ok', true,
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'key', c.key, 'name', c.name, 'blurb', c.blurb, 'icon', c.icon,
        'sort', c.sort, 'kind', c.kind, 'visible', c.visible, 'system', c.system, 'extra', c.extra
      ) order by c.sort, c.name)
      from private.store_categories c
    ), '[]'::jsonb),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'sku', i.sku, 'categoryId', i.category_id, 'name', i.name, 'blurb', i.blurb,
        'cost', i.cost, 'bits', i.bits, 'grants', i.grants, 'sprite', i.sprite, 'thumb', i.thumb,
        'featured', i.featured, 'sort', i.sort, 'visible', i.visible, 'extra', i.extra
      ) order by i.sort, i.name)
      from private.store_items i
    ), '[]'::jsonb),
    'assets', coalesce((
      select jsonb_agg(jsonb_build_object('filename', a.filename, 'kind', a.kind, 'label', a.label) order by a.label, a.filename)
      from private.store_assets a
    ), '[]'::jsonb),
    'looks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', l.id, 'name', l.name, 'gender', l.gender, 'outfit', l.outfit, 'ext', l.ext,
        'groupKey', l.group_key, 'groupLabel', l.group_label, 'games', l.games,
        'pack', l.pack_key, 'sort', l.sort, 'visible', l.visible
      ) order by l.sort, l.name)
      from private.trainer_looks l
    ), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_store_reorder(p_kind text, p_ids jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  idx int := 0;
  elem text;
begin
  perform private.require_staff_edit();
  for elem in select jsonb_array_elements_text(coalesce(p_ids, '[]'::jsonb)) loop
    if p_kind = 'category' then
      update private.store_categories set sort = idx * 10 where id::text = elem or key = elem;
    else
      update private.store_items set sort = idx * 10 where sku = elem;
    end if;
    idx := idx + 1;
  end loop;
  return public.admin_store_get() || jsonb_build_object('message', 'Order saved.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_store_save_category(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cat_id uuid;
  cat_key text;
begin
  perform private.require_staff_edit();
  cat_id := nullif(p_row->>'id', '')::uuid;
  cat_key := lower(regexp_replace(btrim(coalesce(p_row->>'key', p_row->>'name', 'floor')), '[^a-z0-9]+', '-', 'g'));
  cat_key := trim(both '-' from cat_key);
  if cat_key = '' then
    raise exception 'Give this floor a name.';
  end if;
  if cat_id is null then
    insert into private.store_categories (key, name, blurb, icon, sort, kind, visible, system, extra)
    values (
      cat_key,
      coalesce(nullif(p_row->>'name', ''), 'New floor'),
      coalesce(p_row->>'blurb', ''),
      coalesce(nullif(p_row->>'icon', ''), 'poke-ball.png'),
      coalesce((p_row->>'sort')::int, 100),
      coalesce(nullif(p_row->>'kind', ''), 'coins'),
      coalesce((p_row->>'visible')::boolean, true),
      false,
      coalesce(p_row->'extra', '{}'::jsonb)
    )
    returning id into cat_id;
  else
    update private.store_categories
      set name = coalesce(nullif(p_row->>'name', ''), name),
          blurb = coalesce(p_row->>'blurb', blurb),
          icon = coalesce(nullif(p_row->>'icon', ''), icon),
          sort = coalesce((p_row->>'sort')::int, sort),
          kind = case when system then kind else coalesce(nullif(p_row->>'kind', ''), kind) end,
          visible = coalesce((p_row->>'visible')::boolean, visible),
          extra = coalesce(p_row->'extra', extra)
      where id = cat_id;
  end if;
  return public.admin_store_get() || jsonb_build_object('message', 'Floor saved.', 'categoryId', cat_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_store_save_item(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sku text;
  v_extra jsonb;
  v_pack text;
  v_kind text;
  v_status text;
  v_product text;
  v_bits int;
  v_titles jsonb;
begin
  perform private.require_staff_edit();
  v_sku := btrim(coalesce(p_row->>'sku', ''));
  if v_sku = '' then raise exception 'Give this item a SKU.'; end if;
  v_extra := coalesce(p_row->'extra', '{}'::jsonb);
  v_status := lower(btrim(coalesce(p_row->>'status', v_extra->>'status', 'published')));
  if v_status not in ('draft', 'published') then v_status := 'published'; end if;
  v_product := nullif(btrim(coalesce(p_row->>'productKind', v_extra->>'productKind', '')), '');
  v_bits := coalesce((p_row->>'bits')::int, 0);
  if v_product is null then
    v_product := case
      when nullif(v_extra->>'pack','') is not null then 'avatar'
      when v_bits > 0 then 'bits'
      when jsonb_typeof(coalesce(p_row->'grants', '{}'::jsonb)) = 'object'
           and (select count(*) from jsonb_object_keys(coalesce(p_row->'grants', '{}'::jsonb))) > 1 then 'pack'
      else 'item'
    end;
  end if;
  if v_bits < 0 then raise exception 'Bits cost cannot be negative.'; end if;
  if v_bits > 0 then
    perform private.bits_validate_grants(coalesce(p_row->'grants', '{}'::jsonb));
    v_titles := coalesce(p_row->'bitsTitles', v_extra->'bitsTitles', '[]'::jsonb);
    if jsonb_typeof(v_titles) = 'string' then
      v_titles := to_jsonb(string_to_array(v_titles #>> '{}', E'\n'));
    end if;
    if v_status = 'published' then
      if v_bits < 1 then raise exception 'Live Bits products need a Bits cost greater than 0.'; end if;
      if jsonb_typeof(v_titles) <> 'array' or jsonb_array_length(v_titles) < 1 then
        raise exception 'Live Bits products need at least one Twitch Power-Up title.';
      end if;
    end if;
    v_extra := v_extra || jsonb_build_object('bitsTitles', coalesce(v_titles, '[]'::jsonb));
  end if;
  v_extra := v_extra || jsonb_build_object(
    'status', v_status,
    'productKind', v_product,
    'detail', coalesce(p_row->>'detail', v_extra->>'detail')
  );
  select c.kind into v_kind from private.store_categories c where c.id = (p_row->>'categoryId')::uuid;
  if v_kind = 'avatars' then
    v_pack := nullif(btrim(coalesce(v_extra->>'pack', '')), '');
    if v_pack is null then
      v_pack := trim(both '-' from regexp_replace(lower(v_sku), '^avatar-', ''));
      if v_pack = '' then v_pack := v_sku; end if;
      v_extra := v_extra || jsonb_build_object('pack', v_pack);
    end if;
    if v_extra->'looks' is null or jsonb_typeof(v_extra->'looks') <> 'array' then
      v_extra := v_extra || jsonb_build_object('looks', '[]'::jsonb);
    end if;
    v_product := 'avatar';
    v_extra := v_extra || jsonb_build_object('productKind', 'avatar');
  end if;
  if v_kind = 'bits' or v_bits > 0 then
    v_product := 'bits';
    v_extra := v_extra || jsonb_build_object('productKind', 'bits');
  end if;
  insert into private.store_items (
    sku, category_id, name, blurb, cost, bits, grants, sprite, thumb, featured, sort, visible, extra, status
  ) values (
    v_sku, (p_row->>'categoryId')::uuid, coalesce(nullif(p_row->>'name', ''), v_sku),
    coalesce(p_row->>'blurb', ''), coalesce((p_row->>'cost')::int, 0), v_bits,
    case when v_bits > 0 then private.bits_validate_grants(coalesce(p_row->'grants', '{}'::jsonb))
         else private.validate_store_grants(coalesce(p_row->'grants', '{}'::jsonb)) end,
    coalesce(p_row->>'sprite', ''), coalesce(p_row->>'thumb', ''),
    coalesce((p_row->>'featured')::boolean, false), coalesce((p_row->>'sort')::int, 100),
    coalesce((p_row->>'visible')::boolean, true), v_extra, v_status
  )
  on conflict (sku) do update set
    category_id = excluded.category_id, name = excluded.name, blurb = excluded.blurb,
    cost = excluded.cost, bits = excluded.bits, grants = excluded.grants, sprite = excluded.sprite,
    thumb = excluded.thumb, featured = excluded.featured, sort = excluded.sort, visible = excluded.visible,
    extra = excluded.extra, status = excluded.status;
  if v_kind = 'avatars' then
    perform private.sync_avatar_pack_looks(v_extra->>'pack', v_extra->'looks', coalesce(nullif(p_row->>'name', ''), v_sku), coalesce(v_extra->>'games', ''));
  end if;
  return public.admin_store_get() || jsonb_build_object(
    'message', 'Item saved.', 'sku', v_sku, 'status', v_status,
    'bitsCollisions', private.bits_amount_collisions()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_test_act(p_user uuid, p_kind text, p_item text DEFAULT NULL::text, p_round uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  kind text := lower(btrim(coalesce(p_kind, '')));
  snap jsonb;
begin
  perform private.require_hub();
  if p_user is null then
    raise exception 'Pick the Play Tester account.';
  end if;
  if not exists (
    select 1 from public.profiles pr
    where pr.id = p_user and pr.username = 'playtester'
  ) then
    raise exception 'admin_test_act is limited to the Play Tester account.';
  end if;
  if kind not in ('join', 'prepare', 'throw') then
    raise exception 'Kind must be join, prepare, or throw.';
  end if;
  perform set_config('request.jwt.claim.sub', p_user::text, true);
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  perform set_config('request.jwt.claims', json_build_object(
    'sub', p_user::text,
    'role', 'authenticated',
    'aud', 'authenticated'
  )::text, true);
  if kind = 'join' then
    snap := public.play_join(p_round);
  elsif kind = 'prepare' then
    snap := public.play_prepare(p_item, p_round);
  else
    snap := public.play_throw(p_item, p_round);
  end if;
  return coalesce(snap, '{}'::jsonb) || jsonb_build_object('ok', true, 'actedAs', p_user, 'kind', kind, 'item', p_item);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_test_start(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  payload jsonb := coalesce(p_payload, '{}'::jsonb);
  outcome text := lower(btrim(coalesce(payload->>'outcome', payload->>'testOutcome', '')));
  r public.encounter_rounds;
begin
  perform private.require_hub();
  if outcome <> '' and outcome not in ('catch', 'escape') then
    raise exception 'Test outcome must be catch, escape, or empty.';
  end if;
  perform set_config('play.test_outcome', outcome, true);
  perform set_config('play.test_rewards', case when coalesce((payload->>'rewards')::boolean, (payload->>'testRewards')::boolean, false) then 'true' else '' end, true);
  r := private.director_start_now(
    nullif(payload->>'dex', '')::int,
    payload->>'gender',
    case when payload ? 'shiny' then (payload->>'shiny')::boolean else null end,
    'TEST',
    true,
    coalesce(nullif(payload->>'formId', '')::int, nullif(payload->>'pokemonFormId', '')::int)
  );
  return jsonb_build_object(
    'ok', true,
    'roundId', r.id,
    'dex', r.dex,
    'name', r.name,
    'variant', r.variant,
    'gender', r.gender,
    'formId', r.pokemon_form_id,
    'triggerSource', r.trigger_source,
    'deadlines', r.deadlines,
    'testMode', true,
    'testOutcome', r.rules->>'testOutcome',
    'testRewards', coalesce((r.rules->>'testRewards')::boolean, false),
    'message', 'TEST MODE encounter started.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_trainer_reward_action(p_user uuid, p_request uuid, p_action text, p_payload jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_prior private.staff_reward_actions;
  v_profile public.profiles; v_override private.staff_pass_overrides;
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb); v_result jsonb;
  v_grants jsonb; v_key text; v_qty integer; v_kind text; v_error text; v_space_before integer;
BEGIN
  PERFORM private.require_staff_edit();
  IF v_actor IS NULL OR p_user IS NULL OR p_request IS NULL OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'A target, request id and staff reason are required.' USING ERRCODE='22023';
  END IF;
  IF p_action IS NULL OR jsonb_typeof(v_payload)<>'object' OR p_action NOT IN ('pass_on','pass_off','pass_sync','pass_daily','pass_weekly','item','candy','pokemon','title','cosmetic','badge') THEN
    RAISE EXCEPTION 'Unknown reward action.' USING ERRCODE='22023';
  END IF;
  -- Profile row serializes concurrent grants and automation against one trainer.
  SELECT * INTO v_profile FROM public.profiles WHERE id=p_user FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Trainer not found.' USING ERRCODE='22023'; END IF;
  IF private.streamlink_protected_trainer(p_user) THEN
    RAISE EXCEPTION 'This protected trainer needs a separately scoped authorization.' USING ERRCODE='42501';
  END IF;
  INSERT INTO private.staff_reward_actions(request_id,actor_id,target_id,action,payload,reason,status)
  VALUES(p_request,v_actor,p_user,p_action,v_payload,btrim(p_reason),'pending') ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN
    SELECT * INTO v_prior FROM private.staff_reward_actions WHERE request_id=p_request;
    IF v_prior.actor_id<>v_actor OR v_prior.target_id<>p_user OR v_prior.action<>p_action OR v_prior.payload<>v_payload OR v_prior.reason<>btrim(p_reason) THEN
      RAISE EXCEPTION 'Request id is already bound to another action.' USING ERRCODE='22023';
    END IF;
    RETURN v_prior.result || jsonb_build_object('requestId',p_request,'replayed',true);
  END IF;
  BEGIN
    IF p_action IN ('pass_on','pass_off') THEN
      INSERT INTO private.staff_pass_overrides(target_id,active,source_before,subscription_active,subscription_source,subscription_checked_at,actor_id,reason)
      VALUES(p_user,p_action='pass_on',v_profile.pass_source,
        coalesce(v_profile.starlight_pass,false) AND coalesce(v_profile.pass_source,'') IN ('twitch-sub','broadcaster'),
        CASE WHEN v_profile.pass_source IN ('twitch-sub','broadcaster') THEN v_profile.pass_source END,
        v_profile.pass_checked_at,v_actor,btrim(p_reason))
      ON CONFLICT(target_id) DO UPDATE SET active=excluded.active,actor_id=excluded.actor_id,reason=excluded.reason,updated_at=now();
      UPDATE public.profiles SET starlight_pass=p_action='pass_on',updated_at=now() WHERE id=p_user;
      v_result:=jsonb_build_object('ok',true,'message','Staff Pass override saved. It remains until cleared.',
        'sourceBefore',v_profile.pass_source,'activeBefore',v_profile.starlight_pass);
    ELSIF p_action='pass_sync' THEN
      DELETE FROM private.staff_pass_overrides WHERE target_id=p_user RETURNING * INTO v_override;
      IF NOT FOUND THEN RAISE EXCEPTION 'There is no staff override to clear.'; END IF;
      UPDATE public.profiles SET starlight_pass=v_override.subscription_active,
        pass_source=v_override.subscription_source,pass_checked_at=v_override.subscription_checked_at,updated_at=now() WHERE id=p_user;
      v_result:=jsonb_build_object('ok',true,'message','Override cleared. Last recorded subscription state restored; a fresh Twitch check may still be needed.');
    ELSIF p_action IN ('pass_daily','pass_weekly','item') THEN
      IF p_action='item' THEN
        v_key:=v_payload->>'key'; v_qty:=(v_payload->>'qty')::integer;
        IF coalesce(v_qty,0) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'Quantity must be 1 to 10000.'; END IF;
        IF v_key IS NULL OR NOT (v_key=ANY(ARRAY['coins','berry','bait','pokeball','greatball','ultraball','lure','bag_bonus']
          ||private.extra_ball_keys()||private.capture_berry_keys()||private.evo_item_keys()||private.valuable_item_keys())) THEN
          RAISE EXCEPTION 'Item is not enabled for grants.';
        END IF;
        v_grants:=jsonb_build_object(v_key,v_qty);
      ELSE
        v_kind:=CASE WHEN p_action='pass_daily' THEN 'daily' ELSE 'weekly' END;
        v_grants:=private.pass_reward_grants(v_kind);
        IF v_grants IS NULL OR v_grants='{}'::jsonb THEN RAISE EXCEPTION 'Pass reward bundle is unavailable.'; END IF;
      END IF;
      IF EXISTS(SELECT 1 FROM jsonb_each_text(v_grants) e WHERE e.key<>ALL(ARRAY['coins','berry','bait','pokeball','greatball','ultraball','lure','bag_bonus']
        ||private.extra_ball_keys()||private.capture_berry_keys()||private.evo_item_keys()||private.valuable_item_keys())
        OR e.value !~ '^[0-9]+$' OR length(e.value)>5 OR e.value::numeric>10000) THEN RAISE EXCEPTION 'Reward bundle is not valid for full audited delivery.'; END IF;
      SELECT coalesce((SELECT bag_bonus FROM public.inventories WHERE user_id=p_user),0) INTO v_space_before;
      v_result:=private.grant_items(p_user,v_grants,'ADMIN_GRANT','staff-reward:'||p_request::text,'staff-reward:'||p_request::text,true);
      IF coalesce((v_grants->>'bag_bonus')::integer,0)>0 AND
        coalesce((SELECT bag_bonus FROM public.inventories WHERE user_id=p_user),0)-v_space_before<>(v_grants->>'bag_bonus')::integer THEN
        RAISE EXCEPTION 'The inventory-space grant would be capped; nothing was granted.';
      END IF;
      IF NOT coalesce((v_result->>'ok')::boolean,false) OR coalesce((v_result->>'full')::boolean,false) OR coalesce((v_result->>'duplicate')::boolean,false) THEN
        RAISE EXCEPTION 'The complete bundle was not delivered.';
      END IF;
      v_result:=v_result||jsonb_build_object('ok',true,'message','Rewards delivered. Player claim cooldowns were not changed.','requested',v_grants);
    ELSIF p_action='candy' THEN
      v_qty:=(v_payload->>'qty')::integer;
      IF coalesce(v_qty,0) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'Quantity must be 1 to 10000.'; END IF;
      PERFORM public.admin_grant_candy(p_user,(v_payload->>'dex')::integer,v_qty);
      v_result:=jsonb_build_object('ok',true,'message','Evolution Candy delivered.');
    ELSIF p_action='pokemon' THEN
      IF coalesce((v_payload->>'dex')::integer,0) NOT BETWEEN 1 AND 151 OR coalesce((v_payload->>'level')::integer,0) NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION 'Choose Kanto species 1–151 and level 1–100.';
      END IF;
      -- Explicit grant context: canonical generator/validator/persistence, no legacy raw INSERT, no WIRE activation.
      v_result:=private.persist_staff_gift(p_user,(v_payload->>'dex')::integer,(v_payload->>'level')::integer,
        'grant','grant:staff-reward:'||p_request::text,'poke',NULL,coalesce((v_payload->>'shiny')::boolean,false),
        'sl-ref-20261013-227b573',NULL,CASE WHEN coalesce((v_payload->>'shiny')::boolean,false) THEN 'shiny' ELSE 'normal' END,NULL,NULL);
      IF NOT coalesce((v_result->>'ok')::boolean,false) THEN RAISE EXCEPTION 'Canonical generation rejected the gift.'; END IF;
      v_result:=v_result||jsonb_build_object('message','Pokémon delivered through canonical generation.');
    ELSE
      v_key:=v_payload->>'id';
      IF p_action='title' THEN PERFORM public.admin_grant_title(p_user,v_key,btrim(p_reason));
      ELSIF p_action='cosmetic' THEN PERFORM public.admin_grant_cosmetic(p_user,v_key,btrim(p_reason));
      ELSIF p_action='badge' THEN PERFORM public.admin_grant_badge(p_user,v_key,btrim(p_reason)); END IF;
      v_result:=jsonb_build_object('ok',true,'message','Unlockable granted.');
    END IF;
    UPDATE private.staff_reward_actions SET status='succeeded',result=v_result,finished_at=now() WHERE request_id=p_request;
  EXCEPTION WHEN OTHERS THEN
    -- Inner transaction rollback preserves the outer receipt, with no partial gift.
    GET STACKED DIAGNOSTICS v_error=RETURNED_SQLSTATE;
    v_result:=jsonb_build_object('ok',false,'message','The action failed; nothing from this request was granted. Check eligibility, inventory limits and enabled catalog entries before a new attempt.');
    UPDATE private.staff_reward_actions SET status='failed',result=v_result,error_code=v_error,finished_at=now() WHERE request_id=p_request;
  END;
  RETURN v_result||jsonb_build_object('requestId',p_request,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.admin_unlock_catch(p_catch uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.catches;
begin
  if not private.is_play_admin() then raise exception 'Admin only.'; end if;
  select * into c from public.catches where id = p_catch for update;
  if c.id is null then raise exception 'Pokémon not found.'; end if;
  update public.catches set locked = false, reserved_trade_id = null, trade_locked_until = null where id = c.id;
  insert into public.play_console_log (kind, message)
  values ('admin', 'Unlocked catch ' || c.id::text || ' for ' || coalesce(nullif(p_reason, ''), 'support') || ' (dex ' || c.dex::text || ')');
  return jsonb_build_object('ok', true, 'message', 'Lock cleared. Ownership was not changed.');
end;
$function$

CREATE OR REPLACE FUNCTION public.play_sync(p_round_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform private.director_tick_if_due();
  return coalesce(private.play_snapshot(auth.uid(), p_round_id), '{}'::jsonb)
    || jsonb_build_object(
      'console', private.play_console_json(100),
      'supportAlert', private.public_support_alert(),
      'specialEvent', private.special_event_player_payload()
    );
end;
$function$
